template = ('<?xml version="1.0" encoding="UTF-8"?>\n'
            '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" '
            'viewBox="0 0 24 24" fill="none" stroke="currentColor" '
            'stroke-width="2" stroke-linecap="round" stroke-linejoin="round">\n'
            '  {paths}\n</svg>\n')

for name, paths in icons.items():
    file_path = os.path.join(icons_dir, name + '.svg')
    with open(file_path, 'w', encoding='utf-8') as f:
        f.write(template.format(paths=paths))

# Generate QRC file
qrc_path = r'e:\B_ProjectLibrary\PWDVault\src\ui\resources\resources.qrc'
qrc_content = '<!DOCTYPE RCC><RCC version="1.0">\n  <qresource prefix="/">\n'
qrc_content += '    <file>dark.qss</file>\n'
qrc_content += '    <file>light.qss</file>\n'
qrc_content += '    <file>logo.png</file>\n'
for name in sorted(icons.keys()):
    qrc_content += '    <file alias="icons/{0}.svg">icons/{0}.svg</file>\n'.format(name)
qrc_content += '  </qresource>\n</RCC>\n'

with open(qrc_path, 'w', encoding='utf-8') as f:
    f.write(qrc_content)

print('Created {0} icons at {1}'.format(len(icons), icons_dir))
print('QRC at {0}'.format(qrc_path))
